// GetCloudProject calls GET /v1/order/cloud/project/{serviceName}: Get allowed options
//
// Arguments:
//   - serviceName: The project id
//
// Requires the IAM action order:apiovh:cloud/project/get.
func (s *Service) GetCloudProject(ctx context.Context, serviceName string) ([]string, error) {
	return ovh.Call[[]string](ctx, s.c, &ovh.Request{Method: http.MethodGet, Path: ovh.Path("/v1/order/cloud/project/{serviceName}", "serviceName", serviceName)})
}

// AllCloudProjects iterates over every object ListCloudProjects lists, fetching each one with
// GetCloudProject only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllCloudProjects(ctx context.Context) iter.Seq2[[]string, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]string, error) {
			return s.ListCloudProjects(ctx)
		},
		func(ctx context.Context, listedID string) ([]string, error) {
			return s.GetCloudProject(ctx, listedID)
		})
}

